fun testIterables() {
    println("== Iterable / List / Map")
    val xs = listOf("c", "a", "b", "c")
    val it = xs.asIterable()
    println(it.elementAtOrElse(1) { "d$it" })
    println(it.elementAtOrElse(9) { "d$it" })
    println(it.findLast { it < "c" })
    println(it.findLast { it > "z" })
    println(xs.reduceRightIndexed { i, e, acc -> acc + e + i })
    println(xs.reduceRightIndexedOrNull { i, e, acc -> acc + e + i })
    println(emptyList<String>().reduceRightIndexedOrNull { i, e, acc -> acc + e + i })
    println(it.runningReduceIndexed { i, acc, e -> acc + e + i })
    println(it.plusElement("z"))
    println(xs.plusElement("z"))
    val m = mapOf(1 to "a", 2 to "bb", 3 to "c")
    println(m.maxOfWithOrNull(naturalOrder<String>()) { it.value })
    println(m.minOfWithOrNull(naturalOrder<String>()) { it.value })
    println(emptyMap<Int, String>().maxOfWithOrNull(naturalOrder<String>()) { it.value })
}

fun testSequences() {
    println("== Sequence")
    val s = sequenceOf("c", "a", "b", "c")
    println(s.filterNotNullTo(ArrayList<String>()))
    println(sequenceOf("x", null, "y").filterNotNullTo(ArrayList<String>()))
    println(s.associateBy({ it }, { "v$it" }))
    println(s.associateByTo(LinkedHashMap<String, String>(), { it }, { "v$it" }))
    println(s.flatMapIndexedTo(ArrayList<String>()) { i, e -> listOf("$i", e) })
    println(s.groupBy({ it }, { "x$it" }))
    println(s.groupByTo(LinkedHashMap<String, MutableList<String>>()) { it })
    println(s.groupByTo(LinkedHashMap<String, MutableList<String>>(), { it }, { "x$it" }))
    println(s.mapIndexedNotNullTo(ArrayList<String>()) { i, e -> if (i % 2 == 0) e else null })
    println(s.maxOfWith(naturalOrder<String>()) { it + "!" })
    println(s.minOfWith(naturalOrder<String>()) { it + "!" })
    println(s.maxOfWithOrNull(naturalOrder<String>()) { it + "!" })
    println(s.minOfWithOrNull(naturalOrder<String>()) { it + "!" })
    println(emptySequence<String>().minOfWithOrNull(naturalOrder<String>()) { it + "!" })
    try { emptySequence<String>().maxOfWith(naturalOrder<String>()) { it } } catch (e: NoSuchElementException) { println("NSEE") }
    println(sequenceOf("x", "y").requireNoNulls().toList())
    println(s.minusElement("c").toList())
    println(s.plusElement("z").toList())
    println(s.asSequence().toList())
    println(sequenceOf<Byte>(1, 2, 4).average())
    println(sequenceOf<Short>(1, 2, 4).average())
    println(sequenceOf(1L, 2L, 4L).average())
    println(sequenceOf(1f, 2f, 4.5f).average())
}

fun testCharSequences() {
    println("== CharSequence")
    val s = "hello world"
    println(s.elementAtOrElse(1) { 'z' })
    println(s.elementAtOrElse(99) { 'z' })
    println(s.filterIndexedTo(StringBuilder()) { i, c -> i % 2 == 0 && c != 'l' })
    println(s.associateBy({ it }, { it.code }))
    println(s.associateByTo(LinkedHashMap<Char, Char>()) { it.uppercaseChar() })
    println(s.associateByTo(LinkedHashMap<Char, Int>(), { it }, { it.code }))
    println(s.associateTo(LinkedHashMap<Char, Int>()) { it to it.code })
    println(s.associateWithTo(LinkedHashMap<Char, Int>()) { it.code })
    println(s.flatMapIndexed { i, c -> listOf(i, c) })
    println(s.flatMapIndexedTo(ArrayList<Any>()) { i, c -> listOf(i, c) })
    println(s.groupBy({ it }, { it.code }))
    println(s.groupByTo(LinkedHashMap<Char, MutableList<Char>>()) { it })
    println(s.groupByTo(LinkedHashMap<Char, MutableList<Int>>(), { it }, { it.code }))
    println(s.mapIndexedNotNull { i, c -> if (i % 3 == 0) c.code else null })
    println(s.mapIndexedNotNullTo(ArrayList<Int>()) { i, c -> if (i % 3 == 0) c.code else null })
    println(s.max())
    println(s.min())
    println(s.maxOfWith(naturalOrder<Int>()) { it.code })
    println(s.minOfWith(naturalOrder<Int>()) { it.code })
    println(s.maxOfWithOrNull(naturalOrder<Int>()) { it.code })
    println(s.minOfWithOrNull(naturalOrder<Int>()) { it.code })
    println("".minOfWithOrNull(naturalOrder<Int>()) { it.code })
    println(s.reduceRightIndexed { i, c, acc -> if (i % 2 == 0) c else acc })
    println(s.reduceRightIndexedOrNull { i, c, acc -> if (i % 2 == 0) c else acc })
    println("".reduceRightIndexedOrNull { i, c, acc -> if (i % 2 == 0) c else acc })
    try { "".max() } catch (e: NoSuchElementException) { println("NSEE") }
}

fun main() {
    testIterables()
    testSequences()
    testCharSequences()
}
